CREATE OR REPLACE FUNCTION private.assert_cloud_cash_sync_enabled(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  perform private.assert_cloud_pos_sync_enabled(p_context);

  if coalesce((p_context->'features'->>'cloud_cash_sync')::boolean, false) is not true then
    raise exception 'CLOUD_CASH_SYNC_DISABLED' using errcode = 'P0001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_cash_permission(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := private.resolve_pos_actor_type(p_context);
  v_permissions jsonb := coalesce(p_context->'actor_permissions', p_context->'staff_permissions', '{}'::jsonb);
begin
  if v_actor_type = 'admin' then return; end if;
  if v_actor_type = 'staff' and (coalesce((v_permissions->>'cash_register')::boolean, false) is true or coalesce((v_permissions->>'caja')::boolean, false) is true) then return; end if;
  raise exception 'POS_PERMISSION_DENIED:cash_register' using errcode = 'P0001';
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_admin_close_cash_session_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_cash_session_id text DEFAULT NULL::text, p_closing_mode text DEFAULT NULL::text, p_counted_amount numeric DEFAULT NULL::numeric, p_next_shift_fund numeric DEFAULT NULL::numeric, p_reason_code text DEFAULT NULL::text, p_comments text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_admin_auth jsonb;
  v_actor_key text;
begin
  v_context := private.validate_pos_sync_context(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  perform private.assert_cloud_cash_sync_enabled(v_context);

  v_admin_auth := private.require_active_admin_session(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  if coalesce((v_admin_auth->>'success')::boolean, false) is not true then
    raise exception '%', coalesce(v_admin_auth->>'code', 'ADMIN_SESSION_REQUIRED') using errcode = 'P0001';
  end if;

  v_actor_key := private.resolve_cash_actor_key(v_context);

  return private.execute_admin_cash_close_v2(
    (v_admin_auth->>'license_id')::uuid,
    (v_admin_auth->>'device_id')::uuid,
    (v_admin_auth->>'admin_user_id')::uuid,
    (v_admin_auth->>'admin_session_id')::uuid,
    coalesce(
      nullif(btrim(v_admin_auth->'admin_user'->>'display_name'), ''),
      nullif(btrim(v_admin_auth->'admin_user'->>'username'), ''),
      'Administrador'
    ),
    v_actor_key,
    p_cash_session_id,
    p_closing_mode,
    p_counted_amount,
    p_next_shift_fund,
    p_reason_code,
    p_comments,
    p_expected_version,
    p_idempotency_key,
    'cash.admin_close',
    null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_admin_adopt_legacy_cash_session_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_cash_session_id text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb; v_license_id uuid; v_device_id uuid; v_admin_user_id uuid; v_admin_session_id uuid; v_actor_key text;
  v_session public.pos_cash_sessions; v_event public.pos_sync_events; v_response jsonb; v_idem public.pos_idempotency_keys; v_inserted boolean; v_legacy_key text;
begin
  v_context:=private.validate_pos_sync_context(p_license_key,p_device_fingerprint,p_security_token,p_staff_session_token);
  perform private.assert_cloud_cash_sync_enabled(v_context);
  if coalesce(v_context->>'device_role','staff')='staff' then raise exception 'ADMIN_SESSION_REQUIRED' using errcode='P0001'; end if;
  v_license_id:=(v_context->>'license_id')::uuid; v_device_id:=(v_context->>'device_id')::uuid; v_admin_user_id:=(v_context->>'admin_user_id')::uuid; v_admin_session_id:=(v_context->>'admin_session_id')::uuid; v_actor_key:=private.resolve_cash_actor_key(v_context);
  if nullif(btrim(coalesce(p_cash_session_id,'')),'') is null then raise exception 'CASH_SESSION_ID_REQUIRED' using errcode='P0001'; end if;
  v_inserted:=private.insert_pos_idempotency_processing(v_license_id,p_idempotency_key,'cash.identity_adopt','cash_session',p_cash_session_id,null);
  if not v_inserted then
    select * into v_idem from public.pos_idempotency_keys where license_id=v_license_id and idempotency_key=p_idempotency_key limit 1;
    if v_idem.status='completed' and v_idem.response_payload is not null then return v_idem.response_payload; end if;
    return jsonb_build_object('success',false,'code','IDEMPOTENCY_PROCESSING','idempotency_key',p_idempotency_key);
  end if;
  select * into v_session from public.pos_cash_sessions s where s.license_id=v_license_id and s.id=p_cash_session_id and s.deleted_at is null for update;
  if v_session.id is null then raise exception 'CASH_SESSION_NOT_FOUND' using errcode='P0001'; end if;
  if v_session.status<>'open' then raise exception 'CASH_SESSION_NOT_OPEN' using errcode='P0001'; end if;
  if v_session.device_role<>'admin' or v_session.admin_user_id is not null or v_session.actor_key not like 'admin_device:%' then raise exception 'CASH_SESSION_NOT_LEGACY_ADMIN' using errcode='P0001'; end if;
  if p_expected_version is null or p_expected_version<>v_session.server_version then
    v_response:=jsonb_build_object('success',false,'code','VERSION_CONFLICT','cash_session',private.pos_cash_session_to_jsonb(v_session),'idempotency_key',p_idempotency_key); perform private.complete_pos_idempotency(v_license_id,p_idempotency_key,v_response); return v_response;
  end if;
  if exists(select 1 from public.pos_cash_sessions s where s.license_id=v_license_id and s.admin_user_id=v_admin_user_id and s.status='open' and s.deleted_at is null) then raise exception 'ADOPTION_CONFLICT' using errcode='P0001'; end if;
  v_legacy_key:=v_session.actor_key;
  update public.pos_cash_sessions set admin_user_id=v_admin_user_id,actor_key=v_actor_key,updated_at=now(),server_version=server_version+1,last_idempotency_key=p_idempotency_key
    where license_id=v_license_id and id=v_session.id returning * into v_session;
  insert into public.pos_cash_audit_events (license_id,cash_session_id,event_type,actor_device_id,actor_admin_user_id,actor_name,payload)
  values (v_license_id,v_session.id,'ADMIN_CASH_IDENTITY_ADOPTED',v_device_id,v_admin_user_id,private.resolve_cash_actor_name(v_context),jsonb_build_object('cash_session_id',v_session.id,'legacy_actor_key',v_legacy_key,'canonical_actor_key',v_actor_key,'admin_user_id',v_admin_user_id,'admin_session_id',v_admin_session_id,'acting_device_id',v_device_id,'opened_by_device_id',v_session.opened_by_device_id,'expected_cash_total',v_session.expected_cash_total,'previous_server_version',v_session.server_version-1,'server_version',v_session.server_version));
  v_event:=private.record_pos_sync_event(v_license_id,'cash_session',v_session.id,'identity_adopt',v_device_id,null,p_idempotency_key,jsonb_build_object('cash_session_id',v_session.id,'legacy_actor_key',v_legacy_key,'canonical_actor_key',v_actor_key,'admin_user_id',v_admin_user_id),v_session.server_version);
  v_response:=jsonb_build_object('success',true,'cash_session',private.pos_cash_session_to_jsonb(v_session),'event',to_jsonb(v_event),'change_seq',v_event.change_seq,'idempotency_key',p_idempotency_key);
  perform private.complete_pos_idempotency(v_license_id,p_idempotency_key,v_response); return v_response;
exception when unique_violation then
  v_response:=jsonb_build_object('success',false,'code','ADOPTION_CONFLICT','message','Ya existe una caja canónica abierta para esta identidad administrativa.','idempotency_key',p_idempotency_key);
  if v_license_id is not null and p_idempotency_key is not null then
    perform private.complete_pos_idempotency(v_license_id,p_idempotency_key,v_response);
  end if;
  return v_response;
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_device_actor_session(p_license_id uuid, p_device_id uuid, p_device_mode text, p_actor_session_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text := nullif(btrim(coalesce(p_actor_session_token, '')), '');
  v_admin record;
  v_staff record;
  v_admin_valid boolean := false;
  v_staff_valid boolean := false;
begin
  if p_device_mode not in ('admin_only', 'staff_only', 'shared') then
    return jsonb_build_object('success', false, 'code', 'DEVICE_MODE_INVALID');
  end if;

  if v_token is null then
    return jsonb_build_object('success', false, 'code', 'ACTOR_SESSION_REQUIRED');
  end if;

  if p_device_mode in ('admin_only', 'shared') then
    select candidate.id as session_id, candidate.admin_user_id, candidate.expires_at, u.username, u.display_name
    into v_admin
    from (
      select s.id, s.admin_user_id, s.session_token_hash, s.expires_at, s.created_at
      from public.license_admin_sessions s
      where s.license_id = p_license_id and s.device_id = p_device_id and s.revoked_at is null
      order by s.created_at desc limit 3
    ) candidate
    join public.license_admin_users u on u.id = candidate.admin_user_id
    where u.license_id = p_license_id and u.is_owner is true and u.is_active is true
      and extensions.crypt(v_token, candidate.session_token_hash) = candidate.session_token_hash
    limit 1;

    if v_admin.session_id is not null then
      if v_admin.expires_at <= now() then
        update public.license_admin_sessions set revoked_at = coalesce(revoked_at, now()) where id = v_admin.session_id;
      else
        v_admin_valid := true;
      end if;
    end if;
  end if;

  if p_device_mode in ('staff_only', 'shared') then
    select candidate.id as session_id, candidate.staff_user_id, candidate.expires_at,
           s.username, s.display_name, s.role_name, s.permissions, s.is_active as staff_is_active
    into v_staff
    from (
      select ss.id, ss.staff_user_id, ss.session_token_hash, ss.expires_at, ss.created_at
      from public.license_staff_sessions ss
      where ss.license_id = p_license_id and ss.device_id = p_device_id and ss.revoked_at is null
      order by ss.created_at desc limit 3
    ) candidate
    join public.license_staff_users s on s.id = candidate.staff_user_id
    where s.license_id = p_license_id
      and extensions.crypt(v_token, candidate.session_token_hash) = candidate.session_token_hash
    limit 1;

    if v_staff.session_id is not null then
      if v_staff.expires_at <= now() then
        update public.license_staff_sessions set revoked_at = coalesce(revoked_at, now()) where id = v_staff.session_id;
      elsif v_staff.staff_is_active is not true then
        return jsonb_build_object('success', false, 'code', 'STAFF_USER_INACTIVE');
      else
        v_staff_valid := true;
      end if;
    end if;
  end if;

  if v_admin_valid and v_staff_valid then
    return jsonb_build_object('success', false, 'code', 'ACTOR_SESSION_AMBIGUOUS');
  end if;
  if not v_admin_valid and not v_staff_valid then
    return jsonb_build_object('success', false, 'code', 'ACTOR_SESSION_INVALID');
  end if;

  if v_admin_valid then
    update public.license_admin_sessions
    set last_used_at = now()
    where id = v_admin.session_id and last_used_at < now() - interval '30 seconds';
    return jsonb_build_object(
      'success', true,
      'actor_type', 'admin',
      'actor_id', v_admin.admin_user_id,
      'actor_key', 'admin:' || v_admin.admin_user_id::text,
      'actor_session_id', v_admin.session_id,
      'actor_permissions', jsonb_build_object('*', true),
      'admin_user_id', v_admin.admin_user_id,
      'admin_user', jsonb_build_object('id', v_admin.admin_user_id, 'username', v_admin.username, 'display_name', v_admin.display_name, 'is_owner', true)
    );
  end if;

  perform private.touch_license_staff_session_seen(v_staff.session_id, '30 seconds'::interval);
  return jsonb_build_object(
    'success', true,
    'actor_type', 'staff',
    'actor_id', v_staff.staff_user_id,
    'actor_key', 'staff:' || v_staff.staff_user_id::text,
    'actor_session_id', v_staff.session_id,
    'actor_permissions', coalesce(v_staff.permissions, '{}'::jsonb),
    'staff_user_id', v_staff.staff_user_id,
    'staff_user', jsonb_build_object('id', v_staff.staff_user_id, 'username', v_staff.username, 'display_name', v_staff.display_name, 'role_name', v_staff.role_name, 'permissions', coalesce(v_staff.permissions, '{}'::jsonb))
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_pos_sync_context(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license record;
  v_device record;
  v_features jsonb;
  v_actor_token text := nullif(btrim(coalesce(p_staff_session_token, '')), '');
  v_admin_auth jsonb := null;
  v_admin_valid boolean := false;
  v_staff_session record;
  v_staff_valid boolean := false;
  v_actor_type text;
  v_actor_id uuid;
  v_actor_session_id uuid;
  v_actor_permissions jsonb := '{}'::jsonb;
  v_staff_payload jsonb := null;
  v_admin_payload jsonb := null;
begin
  select
    l.id,
    l.license_key,
    entitlement.plan_code,
    entitlement.plan_name,
    entitlement.expires_at,
    entitlement.grace_period_ends,
    entitlement.lifecycle_state,
    entitlement.is_entitled,
    entitlement.is_in_grace,
    entitlement.effective_features
  into v_license
  from public.licenses l
  cross join lateral private.license_entitlement_state_v1(l.id) entitlement
  where l.license_key = p_license_key
  limit 1;

  if v_license.id is null then
    raise exception 'LICENSE_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_license.lifecycle_state = 'administratively_blocked' then
    raise exception 'LICENSE_NOT_ACTIVE' using errcode = 'P0001';
  end if;
  if v_license.is_entitled is not true then
    raise exception 'LICENSE_EXPIRED' using errcode = 'P0001';
  end if;

  select d.id, d.license_id, d.device_fingerprint, d.security_token,
         d.previous_security_token, d.is_active, d.device_mode,
         d.device_role as legacy_device_role,
         d.staff_user_id as legacy_staff_user_id, d.realtime_topic
  into v_device
  from public.license_devices d
  where d.license_id = v_license.id
    and d.device_fingerprint = p_device_fingerprint
  limit 1;

  if v_device.id is null then raise exception 'DEVICE_NOT_ALLOWED' using errcode = 'P0001'; end if;
  if v_device.is_active is not true then raise exception 'DEVICE_NOT_ACTIVE' using errcode = 'P0001'; end if;
  if v_device.security_token is null or nullif(p_security_token, '') is null then
    raise exception 'DEVICE_TOKEN_REQUIRED' using errcode = 'P0001';
  end if;
  if p_security_token <> v_device.security_token
     and (v_device.previous_security_token is null or p_security_token <> v_device.previous_security_token) then
    raise exception 'DEVICE_TOKEN_INVALID' using errcode = 'P0001';
  end if;
  if v_actor_token is null then raise exception 'ACTOR_SESSION_REQUIRED' using errcode = 'P0001'; end if;

  v_features := coalesce(v_license.effective_features, '{}'::jsonb);

  if v_device.device_mode in ('admin_only', 'shared') then
    v_admin_auth := private.require_active_admin_session(
      p_license_key, p_device_fingerprint, p_security_token, v_actor_token
    );
    v_admin_valid := coalesce((v_admin_auth->>'success')::boolean, false);
  end if;

  if v_device.device_mode in ('staff_only', 'shared') then
    select ss.id as session_id, ss.expires_at, s.id as staff_user_id,
           s.username, s.display_name, s.role_name, s.permissions,
           s.is_active as staff_is_active
    into v_staff_session
    from public.license_staff_sessions ss
    join public.license_staff_users s on s.id = ss.staff_user_id
    where ss.license_id = v_license.id
      and ss.device_id = v_device.id
      and s.license_id = v_license.id
      and ss.revoked_at is null
      and extensions.crypt(v_actor_token, ss.session_token_hash) = ss.session_token_hash
    order by ss.created_at desc
    limit 1;

    if v_staff_session.session_id is not null then
      if v_staff_session.expires_at <= now() then
        update public.license_staff_sessions
        set revoked_at = coalesce(revoked_at, now())
        where id = v_staff_session.session_id;
        raise exception 'STAFF_SESSION_EXPIRED' using errcode = 'P0001';
      end if;
      if v_staff_session.staff_is_active is not true then
        raise exception 'STAFF_USER_INACTIVE' using errcode = 'P0001';
      end if;
      v_staff_valid := true;
    end if;
  end if;

  if v_admin_valid and v_staff_valid then
    raise exception 'ACTOR_SESSION_AMBIGUOUS' using errcode = 'P0001';
  end if;
  if not v_admin_valid and not v_staff_valid then
    raise exception 'ACTOR_SESSION_INVALID' using errcode = 'P0001';
  end if;

  if v_admin_valid then
    v_actor_type := 'admin';
    v_actor_id := (v_admin_auth->>'admin_user_id')::uuid;
    v_actor_session_id := (v_admin_auth->>'admin_session_id')::uuid;
    v_actor_permissions := jsonb_build_object('*', true);
    v_admin_payload := v_admin_auth->'admin_user';
  else
    v_actor_type := 'staff';
    v_actor_id := v_staff_session.staff_user_id;
    v_actor_session_id := v_staff_session.session_id;
    v_actor_permissions := coalesce(v_staff_session.permissions, '{}'::jsonb);
    v_staff_payload := jsonb_build_object(
      'id', v_staff_session.staff_user_id,
      'username', v_staff_session.username,
      'display_name', v_staff_session.display_name,
      'role_name', v_staff_session.role_name,
      'permissions', v_actor_permissions
    );
    perform private.touch_license_staff_session_seen(v_staff_session.session_id, '30 seconds'::interval);
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'license_id', v_license.id,
    'license_key', v_license.license_key,
    'device_id', v_device.id,
    'device_mode', v_device.device_mode,
    'legacy_device_role', v_device.legacy_device_role,
    'actor_type', v_actor_type,
    'actor_id', v_actor_id,
    'actor_key', v_actor_type || ':' || v_actor_id::text,
    'actor_session_id', v_actor_session_id,
    'actor_permissions', v_actor_permissions,
    'device_role', v_actor_type,
    'staff_user_id', case when v_actor_type = 'staff' then v_actor_id else null end,
    'staff_permissions', case when v_actor_type = 'staff' then v_actor_permissions else '{}'::jsonb end,
    'staff_user', v_staff_payload,
    'admin_user_id', case when v_actor_type = 'admin' then v_actor_id else null end,
    'admin_session_id', case when v_actor_type = 'admin' then v_actor_session_id else null end,
    'admin_user', v_admin_payload,
    'plan_code', v_license.plan_code,
    'plan_name', v_license.plan_name,
    'features', v_features,
    'realtime_topic', v_device.realtime_topic,
    'license_lifecycle_state', v_license.lifecycle_state,
    'license_is_in_grace', v_license.is_in_grace,
    'license_expires_at', v_license.expires_at,
    'license_grace_period_ends', v_license.grace_period_ends
  ));
end;
$function$
